<?php
/** CLI-only local disposable review data; no enrollment or email. */
if(PHP_SAPI!=='cli')throw new RuntimeException('CLI_REQUIRED');
if(!defined('ABSPATH')){define('DOING_CRON',true);require dirname(__DIR__,5).'/wp-load.php';}
if(!in_array(parse_url(home_url(),PHP_URL_HOST),array('localhost','127.0.0.1'),true))throw new RuntimeException('LOCAL_WORDPRESS_REQUIRED');
add_filter('pre_wp_mail',static function(){return false;},PHP_INT_MAX);wp_set_current_user(1);
require_once dirname(__DIR__,2).'/includes/study-engine/builder.php';require_once dirname(__DIR__,2).'/includes/assessment-editor/runtime/Owner.php';
use EIPSI\StudyEngine\Builder as B;use EIPSI\StudyEngine\Persistence as P;use EIPSI\AssessmentEditor as A;
$manifest=get_option('eipsi_redesign_review_v1');if($manifest){echo wp_json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)."\n";exit;}
$s=new B\Service(new P\Database($GLOBALS['wpdb']));$owner=new A\Runtime\Owner();$owner->store->install();$versions=array();
foreach(array('Bienestar','Energía','Descanso') as $i=>$title){$d=json_decode(file_get_contents(dirname(__DIR__,2).'/tests/assessment-editor/functional-fixture.json'),true);$d['id']='AE_REDESIGN_REVIEW_'.$i;$d['title']='Revisión descartable — '.$title;$d['elements']=array_values(array_filter($d['elements'],static function($e){return $e['type']==='text';}));$d['elements'][0]['properties']['label']='¿Cómo describirías tu '.$title.'?';$d['elements'][0]['properties']['label_html']='<p>¿Cómo describirías tu <strong>'.$title.'</strong>?</p>';$d['flow']['pages']=array();$d=A\Definition::validate($d);$prior=get_option(A\Repository::PREFIX.$d['id'])?A\Repository::load($d['id']):null;if(!$prior)A\Repository::save($d,0);$versions[]=$owner->publish($d['id'],$prior['revision']??1)['version_id'];}
function rv_block($d,$id,$parent,$role,$pos=0){$n=B\Draft::block($id,$d['id'],$parent,'MACRO',$pos);$n['metadata']=array('label'=>$id,'role'=>$role,'independent_children'=>true,'duration_days'=>14);$n['children_strategy']='PARALLEL_AVAILABLE';$n['schedule']=B\Draft::schedule();$n['schedule']['timezone_policy']='PARTICIPANT_LOCAL';return $n;}
function rv_assessment($d,$id,$parent,$v,$pos=0){$n=B\Draft::block($id,$d['id'],$parent,'MICRO',$pos);$n['metadata']=array('label'=>$id,'native_version_id'=>$v,'scheduled_interaction'=>array('delivery'=>'START','window_seconds'=>3600,'reminders'=>array(3600,7200)));$n['schedule']=B\Draft::schedule();$n['schedule']['timezone_policy']='PARTICIPANT_LOCAL';$n['schedule']['temporal_rule']=array('kind'=>'LOCAL_DAY_TIME','day_index'=>1,'time'=>'09:00');$n['schedule']['window']=array('kind'=>'DURATION','duration'=>array('kind'=>'ELAPSED','seconds'=>86400));return $n;}
function rv_random($ids,$n){return array('strategy'=>'WEIGHTED_RANDOM','scope'=>'EXECUTION','candidates'=>$ids,'select_n'=>null,'draw_count'=>$n,'weights'=>array_combine($ids,array_map(static function($i){return $i+1;},array_keys($ids))),'order'=>'DEFINITION','algorithm_version'=>'EIPSI_RANDOM_V1');}
$t=$s->create(array('name'=>'Revisión descartable Transversal'),'REDESIGN_REVIEW_TRANS_V1');$d=$t['definition'];$n=B\Draft::block('REV_IMMEDIATE',$d['id'],$d['root_block_ids'][0],'MICRO',0);$n['metadata']=array('label'=>'Bienestar inmediato','native_version_id'=>$versions[0]);$n['schedule']=B\Draft::schedule();$d['nodes'][]=$n;$t=$s->save($t['id'],0,'REVIEW_SAVE_TRANS',$d);$t=$s->publish($t['id'],$t['revision'],array());$t=$s->activate($t['id'],$t['revision'],'OPEN');
$l=$s->create(array('name'=>'Revisión descartable Longitudinal'),'REDESIGN_REVIEW_LONG_V1');$d=$l['definition'];$d['protocol_metadata']['study_type']='LONGITUDINAL';$d=EIPSI\StudyEngine\Longitudinal\Configuration::apply($d,array('email_enabled'=>false,'reminder_offsets'=>array()));$r=rv_block($d,'REV_BLOCK_RANDOM',$d['root_block_ids'][0],'BLOCK_RANDOMIZATION');$r['metadata']['label']='Selección de bloques';$r['children_strategy']='WEIGHTED_RANDOM';$r['randomization']=rv_random(array('REV_BLOCK_A','REV_BLOCK_B'),2);$d['nodes'][]=$r;
foreach(array('REV_BLOCK_A','REV_BLOCK_B') as $i=>$id){$n=rv_block($d,$id,$r['id'],'LONGITUDINAL_BLOCK',$i);$n['metadata']['label']=$i?'Bloque B — solapado':'Bloque A';$d['nodes'][]=$n;}
$n=rv_assessment($d,'REV_FIXED','REV_BLOCK_A',$versions[0]);$n['metadata']['label']='Bienestar · Día 1, 09:00';$d['nodes'][]=$n;
$n=rv_assessment($d,'REV_DELIVERY','REV_BLOCK_B',$versions[1]);$n['metadata']['label']='Energía · entrega aleatoria 09:00–10:00';$n['metadata']['scheduled_interaction']['delivery']='RANDOM';$d['nodes'][]=$n;
$n=rv_assessment($d,'REV_RELATIVE','REV_BLOCK_A',$versions[2],1);$n['metadata']['label']='Descanso · +7 días desde Bienestar';$n['metadata']['relative_day']=8;$n['metadata']['relative_time']='09:00';$n['schedule']['anchor']='SPECIFIC_BLOCK_COMPLETED';$n['schedule']['anchor_ref']='REV_FIXED';$n['schedule']['occurrence_selector']=array('kind'=>'SINGLE');$n['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'CALENDAR','amount'=>7,'unit'=>'DAY'));$d['nodes'][]=$n;
$local=rv_block($d,'REV_LOCAL','REV_BLOCK_A','LOCAL_RANDOMIZATION',2);$local['metadata']['label']='Una evaluación de dos · Día 2';$local['metadata']['scheduled_interaction']=array('delivery'=>'START','window_seconds'=>3600,'reminders'=>array(3600));$local['schedule']['temporal_rule']=array('kind'=>'LOCAL_DAY_TIME','day_index'=>2,'time'=>'09:00');$local['schedule']['window']=array('kind'=>'DURATION','duration'=>array('kind'=>'ELAPSED','seconds'=>86400));$local['children_strategy']='WEIGHTED_RANDOM';$local['randomization']=rv_random(array('REV_CANDIDATE_1','REV_CANDIDATE_2'),1);$d['nodes'][]=$local;
foreach(array('REV_CANDIDATE_1','REV_CANDIDATE_2') as $i=>$id){$n=rv_assessment($d,$id,$local['id'],$versions[$i+1],$i);unset($n['metadata']['scheduled_interaction']);$n['schedule']=B\Draft::schedule('BLOCK_AVAILABLE',$local['id']);$n['schedule']['window']=$local['schedule']['window'];$d['nodes'][]=$n;}
$l=$s->save($l['id'],0,'REVIEW_SAVE_LONG',$d);$validation=$s->validate($l['id']);if($validation['issues'])throw new RuntimeException(wp_json_encode($validation['issues']));
$manifest=array('admin_url'=>admin_url('admin.php?page=eipsi-study-builder'),'transversal'=>array('id'=>$t['id'],'study_id'=>$t['study_id'],'name'=>$t['administration']['name'],'url'=>$t['public_url']),'longitudinal'=>array('id'=>$l['id'],'study_id'=>$l['study_id'],'name'=>$l['administration']['name'],'state'=>'DRAFT','email_enabled'=>false),'native_versions'=>$versions,'participants_created'=>0,'emails_sent'=>0);update_option('eipsi_redesign_review_v1',$manifest,false);echo wp_json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)."\n";
